const fs = require('fs');
const path = require('path');
const item = $input.item.json;

const BASE = '/home/node/.n8n/obsidian/DB_Obsidian/╨Ь╨Ю╨Щ ╨в╨а╨Х╨Щ╨Ф╨Ш╨Э╨У';

const partFolder = (item.part || '╨з╨░╤Б╤В╤М 13. ╨Я╨а╨Ю╨з╨Х╨Х').replace(/[/\\]/g, ' тАФ ');
const chapterName = item.chapter || '╨У╨╗╨░╨▓╨░ 13.1. ╨Я╤А╨╛╤З╨╡╨╡';
const safeChapter = chapterName.replace(/[/\\]/g, ' тАФ ');
const fullPath = path.join(BASE, partFolder, safeChapter + '.md');

const dir = path.dirname(fullPath);
if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });

let existingContent = '';
try {
  existingContent = fs.readFileSync(fullPath, 'utf8');
} catch (e) {
  const header = `# ${chapterName}\n\n> ╨з╨░╤Б╤В╤М: ${partFolder}\n\n`;
  try { fs.writeFileSync(fullPath, header, 'utf8'); } catch (err) {}
