const item = $input.item.json;
return {
  json: {
    model: "nvidia/nemotron-3-super-120b-a12b:free",
    messages: [{ role: "user", content: item.aiPrompt }],
    response_format: { type: "json_object" },
    reasoning: { enabled: false },
